import 'package:flutter/material.dart';
import '../models/for_you_mix.dart';
import '../services/for_you_service.dart';
import '../services/playback_controller.dart';
import '../l10n/translation_core.dart';
import '../theme/liquid_glass.dart';
import '../theme/typography.dart';
import '../widgets/autogenerated_mix_cover.dart';

/// ForYouStage: Autogenerated YouTube Music-style algorithmic mixes
/// with shapey Material You 3 cards and procedural vector artwork.
class ForYouStage extends StatefulWidget {
  final VoidCallback? onOpenNowPlaying;

  const ForYouStage({super.key, this.onOpenNowPlaying});

  @override
  State<ForYouStage> createState() => _ForYouStageState();
}

class _ForYouStageState extends State<ForYouStage> {
  ForYouArtStyle? _selectedStyleOverride;

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return ListenableBuilder(
      listenable: Listenable.merge([PlaybackController.instance, AppLocalizations.instance]),
      builder: (context, _) {
        final controller = PlaybackController.instance;
        final libraryTracks = controller.libraryTracks;
        final mixes = ForYouService.instance.generateMixes(context, libraryTracks);
        final heroMix = mixes.isNotEmpty ? mixes.first : null;

        return ListView(
          physics: const BouncingScrollPhysics(),
          padding: const EdgeInsets.symmetric(horizontal: 20.0, vertical: 16.0),
          children: [
            // 1. Stage Header
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      context.tr('for_you_title'),
                      style: AttuneTypography.soraHeading(
                        color: colorScheme.onSurface,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      context.tr('for_you_subtitle'),
                      style: AttuneTypography.jakartaBodySmall(
                        color: colorScheme.onSurface.withValues(alpha: 0.6),
                      ),
                    ),
                  ],
                ),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                  decoration: BoxDecoration(
                    color: colorScheme.primary.withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: colorScheme.primary.withValues(alpha: 0.3)),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(Icons.auto_awesome_rounded, size: 14, color: colorScheme.primary),
                      const SizedBox(width: 4),
                      Text(
                        'M3 For You',
                        style: AttuneTypography.soraBadge(
                          color: colorScheme.primary,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),

            const SizedBox(height: 16),

            // 2. Interactive Sample Art Style Switcher
            SizedBox(
              height: 38,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                itemCount: ForYouArtStyle.values.length + 1,
                separatorBuilder: (_, _) => const SizedBox(width: 8),
                itemBuilder: (context, index) {
                  if (index == 0) {
                    final isSelected = _selectedStyleOverride == null;
                    return ChoiceChip(
                      label: Text('Auto Dynamic', style: AttuneTypography.soraBadge(color: isSelected ? colorScheme.primary : colorScheme.onSurface.withValues(alpha: 0.7))),
                      selected: isSelected,
                      selectedColor: colorScheme.primary.withValues(alpha: 0.22),
                      backgroundColor: Colors.white.withValues(alpha: 0.06),
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
                      side: BorderSide(color: isSelected ? colorScheme.primary.withValues(alpha: 0.5) : Colors.white12),
                      onSelected: (_) => setState(() => _selectedStyleOverride = null),
                    );
                  }

                  final style = ForYouArtStyle.values[index - 1];
                  final isSelected = _selectedStyleOverride == style;

                  return ChoiceChip(
                    label: Text(style.label, style: AttuneTypography.soraBadge(color: isSelected ? colorScheme.primary : colorScheme.onSurface.withValues(alpha: 0.7))),
                    selected: isSelected,
                    selectedColor: colorScheme.primary.withValues(alpha: 0.22),
                    backgroundColor: Colors.white.withValues(alpha: 0.06),
                    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
                    side: BorderSide(color: isSelected ? colorScheme.primary.withValues(alpha: 0.5) : Colors.white12),
                    onSelected: (_) => setState(() => _selectedStyleOverride = style),
                  );
                },
              ),
            ),

            const SizedBox(height: 20),

            // 3. Featured Hero Mix Card (Shapey Material You 3 Hero)
            if (heroMix != null) ...[
              LiquidGlassContainer(
                padding: const EdgeInsets.all(18),
                borderRadius: 28,
                surfaceAlpha: 0.16,
                child: Row(
                  children: [
                    AutogeneratedMixCover(
                      mix: heroMix,
                      size: 110,
                      borderRadius: 22,
                      styleOverride: _selectedStyleOverride,
                    ),
                    const SizedBox(width: 16),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Container(
                            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                            decoration: BoxDecoration(
                              color: heroMix.primaryColor.withValues(alpha: 0.2),
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Text(
                              'FEATURED DAILY MIX',
                              style: AttuneTypography.soraBadge(
                                color: heroMix.primaryColor,
                                fontSize: 9.5,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ),
                          const SizedBox(height: 6),
                          Text(
                            heroMix.title,
                            style: AttuneTypography.soraTitleMedium(
                              color: colorScheme.onSurface,
                              fontWeight: FontWeight.w700,
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                          const SizedBox(height: 4),
                          Text(
                            heroMix.subtitle,
                            style: AttuneTypography.jakartaBodySmall(
                              color: colorScheme.onSurface.withValues(alpha: 0.6),
                            ),
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                          ),
                          const SizedBox(height: 10),
                          FilledButton.icon(
                            style: FilledButton.styleFrom(
                              backgroundColor: colorScheme.primary,
                              foregroundColor: colorScheme.onPrimary,
                              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
                              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                            ),
                            icon: const Icon(Icons.play_arrow_rounded, size: 18),
                            label: Text(
                              context.tr('for_you_play_mix'),
                              style: AttuneTypography.soraTitleSmall(color: colorScheme.onPrimary, fontSize: 13),
                            ),
                            onPressed: () => ForYouService.instance.playMix(
                              heroMix,
                              onOpenNowPlaying: widget.onOpenNowPlaying,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 24),
            ],

            // 4. Section: Autogenerated Vibe Stations
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  'AUTOGENERATED VIBE MIXES',
                  style: AttuneTypography.soraBadge(
                    color: colorScheme.primary,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                Text(
                  context.tr('home_total_tracks', {'count': libraryTracks.length}),
                  style: AttuneTypography.soraBadge(
                    color: colorScheme.onSurface.withValues(alpha: 0.4),
                  ),
                ),
              ],
            ),

            const SizedBox(height: 14),

            // 5. Shapey Grid / Cards for All Mixes
            ...mixes.map((mix) {
              return Padding(
                padding: const EdgeInsets.only(bottom: 12.0),
                child: LiquidGlassContainer(
                  padding: const EdgeInsets.all(14),
                  borderRadius: 22,
                  surfaceAlpha: 0.10,
                  onTap: () => ForYouService.instance.playMix(
                    mix,
                    onOpenNowPlaying: widget.onOpenNowPlaying,
                  ),
                  child: Row(
                    children: [
                      AutogeneratedMixCover(
                        mix: mix,
                        size: 72,
                        borderRadius: 18,
                        styleOverride: _selectedStyleOverride,
                      ),
                      const SizedBox(width: 14),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              mix.title,
                              style: AttuneTypography.soraSubheading(
                                color: colorScheme.onSurface,
                                fontWeight: FontWeight.w600,
                              ),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                            ),
                            const SizedBox(height: 3),
                            Text(
                              mix.subtitle,
                              style: AttuneTypography.jakartaBodySmall(
                                color: colorScheme.onSurface.withValues(alpha: 0.6),
                              ),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                            ),
                            const SizedBox(height: 6),
                            Row(
                              children: [
                                Icon(Icons.queue_music_rounded, size: 13, color: mix.primaryColor),
                                const SizedBox(width: 4),
                                Text(
                                  context.tr('for_you_mix_tracks', {'count': mix.tracks.length}),
                                  style: AttuneTypography.soraMetric(
                                    color: colorScheme.onSurface.withValues(alpha: 0.5),
                                    fontSize: 10,
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                      IconButton.filledTonal(
                        style: IconButton.styleFrom(
                          backgroundColor: colorScheme.surfaceContainerHighest.withValues(alpha: 0.3),
                          foregroundColor: colorScheme.primary,
                        ),
                        icon: const Icon(Icons.play_arrow_rounded, size: 22),
                        onPressed: () => ForYouService.instance.playMix(
                          mix,
                          onOpenNowPlaying: widget.onOpenNowPlaying,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }),

            const SizedBox(height: 80),
          ],
        );
      },
    );
  }
}
